B.c3P=new A.a6o(B.di,B.ku,B.E_,"context-free pumping lemma",B.ay9,B.asQ,"test/fixtures/interoperability/pumping_lemma_context_free_canonical.jff")
B.ay4=new A.fx("pumping-lemma.regular.jflap.v1")
B.atD=new A.dI("codec.pumping-lemma.regular.jflap")
B.c3Q=new A.a6o(B.bt,B.jz,B.DZ,"regular pumping lemma",B.ay4,B.atD,"test/fixtures/interoperability/pumping_lemma_regular_canonical.jff")
